import{bQ as r,aZ as d,aL as o,u as n,G as e,I as i}from"./chunks/framework.C1gZXFVa.js";const g=JSON.parse('{"title":"coinex-entrust 启动流程","description":"委托服务启动后如何就绪：导出接口、订阅消息，业务数据按请求懒加载。","frontmatter":{"title":"coinex-entrust 启动流程","description":"委托服务启动后如何就绪：导出接口、订阅消息，业务数据按请求懒加载。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070502"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070502"}],["meta",{"property":"og:title","content":"coinex-entrust 启动流程 · TGEX"}],["meta",{"property":"og:description","content":"委托服务启动后如何就绪：导出接口、订阅消息，业务数据按请求懒加载。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"coinex-entrust 启动流程 · TGEX"}],["meta",{"name":"twitter:description","content":"委托服务启动后如何就绪：导出接口、订阅消息，业务数据按请求懒加载。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"coinex-entrust 启动流程\\",\\"description\\":\\"委托服务启动后如何就绪：导出接口、订阅消息，业务数据按请求懒加载。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070502\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070502\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070502.md","filePath":"07.现货手册/05.核心交易流程/02.委托初始化链路.md"}'),s={name:"pages/070502.md"};function h(c,t,p,l,u,b){const a=d("Flow");return o(),n("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="coinex-entrust-启动流程" tabindex="-1">coinex-entrust 启动流程 <a class="header-anchor" href="#coinex-entrust-启动流程" aria-label="Permalink to &quot;coinex-entrust 启动流程&quot;">​</a></h1><div class="doc-lead">委托服务没有「按交易对灌订单簿」那种重初始化；启动后的业务准备是：接口可对外、消息可消费、缓存按第一次请求再装。</div><p>工程：<code>coinex-entrust</code>。委托侧<strong>没有</strong>撮合那种「按交易对灌订单簿」的全量预热。本文说明启动后如何就绪。</p><h2 id="和撮合初始化的差别" tabindex="-1">和撮合初始化的差别 <a class="header-anchor" href="#和撮合初始化的差别" aria-label="Permalink to &quot;和撮合初始化的差别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>委托</th><th>撮合</th></tr></thead><tbody><tr><td>启动时是否按交易对恢复委托</td><td>否</td><td>是</td></tr><tr><td>交易对 / 费率何时进本地缓存</td><td>首次业务调用再装</td><td>启动时批量装入</td></tr><tr><td>启动后立刻要做的业务准备</td><td>接口可对外、消息可消费</td><td>恢复订单簿并开放接单</td></tr></tbody></table><p>读本篇时不要期待「先 list 全部交易对再灌内存」的步骤——那一步在撮合 / 行情侧更明显。</p><h2 id="总览顺序" tabindex="-1">总览顺序 <a class="header-anchor" href="#总览顺序" aria-label="Permalink to &quot;总览顺序&quot;">​</a></h2>',8)),i(a,{steps:["Apollo 与基础设施就绪","导出委托 Dubbo 接口","注册 EventBus 与 MQ 消费","心跳探库","进程保活","首次请求时懒加载交易对等"]}),t[1]||(t[1]=e('<h2 id="_1-容器起来之后有什么" tabindex="-1">1. 容器起来之后有什么 <a class="header-anchor" href="#_1-容器起来之后有什么" aria-label="Permalink to &quot;1. 容器起来之后有什么&quot;">​</a></h2><h3 id="_1-1-基础设施" tabindex="-1">1.1 基础设施 <a class="header-anchor" href="#_1-1-基础设施" aria-label="Permalink to &quot;1.1 基础设施&quot;">​</a></h3><p>数据源、MyBatis、Redis（Jedis / Redisson）、Elasticsearch、RocketMQ Producer/Consumer、Dubbo 注册与协议端口在 Spring 刷新阶段完成。<br> Consumer 侧通常 <code>check=false</code>：<strong>不因下游暂时不在线而拒绝启动</strong>。</p><h3 id="_1-2-导出的业务能力-provider" tabindex="-1">1.2 导出的业务能力（Provider） <a class="header-anchor" href="#_1-2-导出的业务能力-provider" aria-label="Permalink to &quot;1.2 导出的业务能力（Provider）&quot;">​</a></h3><p>启动完成后，本进程对外提供委托相关 Dubbo 接口（如下单 / 撤单门面、统计、机器人刷单、与行情相关的委托查询等）。<br> 客户端或撮合、账务补偿链路能发现这些接口，是 entrust「业务上线」的第一层含义。</p><h3 id="_1-3-eventbus-注册-contextrefreshedevent" tabindex="-1">1.3 EventBus 注册（<code>ContextRefreshedEvent</code>） <a class="header-anchor" href="#_1-3-eventbus-注册-contextrefreshedevent" aria-label="Permalink to &quot;1.3 EventBus 注册（`ContextRefreshedEvent`）&quot;">​</a></h3><p>注册例如：</p><table tabindex="0"><thead><tr><th>监听</th><th>作用</th></tr></thead><tbody><tr><td>限购变更</td><td>PRE 等活动限购计数</td></tr><tr><td>批量撤单</td><td>异步批量撤</td></tr><tr><td>账务超时</td><td>委单账务超时写库 / 补偿相关</td></tr></tbody></table><p>此时只是<strong>注册</strong>，不会在启动瞬间跑一遍全站委托。</p><h3 id="_1-4-rocketmq-消费订阅" tabindex="-1">1.4 RocketMQ 消费订阅 <a class="header-anchor" href="#_1-4-rocketmq-消费订阅" aria-label="Permalink to &quot;1.4 RocketMQ 消费订阅&quot;">​</a></h3><p>启动后订阅的主题包括（以代码启用为准）：预撮合处理、历史委托转 ES、账务超时补偿等。<br> 有积压时会在启动后立刻开始消费；没有预热「先读完所有历史委托再对外」。</p><p>部分旧 Listener 逻辑已注释或降级，以当前仍带 <code>@Component</code> / <code>@RocketMQMessageListener</code> 的为准。</p><h3 id="_1-5-心跳" tabindex="-1">1.5 心跳 <a class="header-anchor" href="#_1-5-心跳" aria-label="Permalink to &quot;1.5 心跳&quot;">​</a></h3><p><code>HeartbeatService</code> 在端口上监听探活；探测时执行类似「查一条委托」的轻量 SQL，确认库连通。<br> 心跳通过只说明进程 + 数据库探针 OK，不保证撮合各交易对已开放接单。</p><h3 id="_1-6-applicationrunner" tabindex="-1">1.6 ApplicationRunner <a class="header-anchor" href="#_1-6-applicationrunner" aria-label="Permalink to &quot;1.6 ApplicationRunner&quot;">​</a></h3><p><code>EntrustApp</code> 实现了 <code>ApplicationRunner</code>，但业务体为空。Ready 后没有「只跑一次」的全量 init。</p><h3 id="_1-7-启动后约-1-秒的定时任务" tabindex="-1">1.7 启动后约 1 秒的定时任务 <a class="header-anchor" href="#_1-7-启动后约-1-秒的定时任务" aria-label="Permalink to &quot;1.7 启动后约 1 秒的定时任务&quot;">​</a></h3><p><code>MqService</code> 开始扫描失败 MQ 重试队列，属于运维向补偿，不是交易对预热。</p><h2 id="_2-业务数据何时加载" tabindex="-1">2. 业务数据何时加载 <a class="header-anchor" href="#_2-业务数据何时加载" aria-label="Permalink to &quot;2. 业务数据何时加载&quot;">​</a></h2><p>下列本地缓存均为 <strong>LoadingCache / 按需 Redis</strong>，启动时不 bulk load：</p><table tabindex="0"><thead><tr><th>缓存</th><th>典型内容</th><th>触发时机</th></tr></thead><tbody><tr><td>商户交易对</td><td>partner + trade</td><td>首次下单 / 查对</td></tr><tr><td>币种</td><td>coinId</td><td>首次用到该币</td></tr><tr><td>用户费率 / VIP</td><td>用户维度</td><td>首次算费</td></tr><tr><td>商户信息</td><td>partnerId</td><td>首次按商户处理</td></tr><tr><td>限购活动</td><td>tradeId</td><td>首次触及 PRE 限购</td></tr><tr><td>委单 JSON</td><td>entrustId</td><td>读写单笔委托</td></tr></tbody></table><p>因此：<strong>第一次真实下单</strong>才会去 Dubbo 拉交易对规则、用户状态等；启动日志里看不到「初始化交易对 success」一类撮合式输出是正常的。</p><h2 id="_3-就绪含义" tabindex="-1">3. 就绪含义 <a class="header-anchor" href="#_3-就绪含义" aria-label="Permalink to &quot;3. 就绪含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>含义</th></tr></thead><tbody><tr><td>框架 Ready</td><td>Spring 完成，进程保活</td></tr><tr><td>接口 Ready</td><td>Dubbo 委托 API 已注册</td></tr><tr><td>消息 Ready</td><td>相关 Consumer 已订阅</td></tr><tr><td>探活 Ready</td><td>心跳查库成功</td></tr><tr><td>业务热路径 Ready</td><td>不在启动完成时保证；取决于首次请求时下游 account / match / coin 是否可用</td></tr></tbody></table><p>下单主路径（V1）会调账务占用、撮合执行等；那些依赖在<strong>请求时</strong>校验，而不是在 entrust 启动时预检全部 Provider。</p><h2 id="_4-和交易闭环的关系" tabindex="-1">4. 和交易闭环的关系 <a class="header-anchor" href="#_4-和交易闭环的关系" aria-label="Permalink to &quot;4. 和交易闭环的关系&quot;">​</a></h2><p>贯穿示例里「提交买单 / 撤单」请求首先打到委托服务：校验规则、驱动账务冻结、再进入撮合。<br> 委托服务启动只保证「门面在」；「盘口里已有历史挂单」是撮合初始化恢复出来的，见<a href="/pages/070503">撮合初始化链路</a>。<br> 账务占用依赖<a href="/pages/070504">账务初始化链路</a>；业务语义见<a href="/pages/070501">业务流程</a>。</p>',27))])}const m=r(s,[["render",h]]);export{g as __pageData,m as default};
